{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "value",
      "type": "string",
      "description": "The currently selected value (controlled).",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: string) => void",
      "description": "Callback fired when a segment is selected.",
      "required": true
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the radio group (used as aria-label, never rendered visually).",
      "required": true
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size variant for the control.",
      "default": "'md'"
    },
    {
      "name": "layout",
      "type": "'hug' | 'fill'",
      "description": "Layout mode. hug (default) sizes segments to content, capped at the container width (segment labels truncate when it is too narrow); fill stretches them equally to fill the container.",
      "default": "'hug'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the entire control is disabled. The selected segment keeps the Tab stop, announced as disabled (aria-disabled), and nothing can be selected.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the control is disabled. Applies to the whole-group disabled state (isDisabled), not per segment. With isDisabled, shows a tooltip on hover/keyboard focus, and the reason describes each segment (selection stays blocked). Use this instead of wrapping a disabled SegmentedControl in Tooltip, so the reason is attached to the control itself."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "SegmentedControlItem children.",
      "slotElements": [
        {
          "__element": "SegmentedControlItem",
          "props": {
            "label": "Option",
            "value": "option"
          }
        }
      ],
      "required": true
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value: not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
